<?php declare(strict_types=1);namespace App\Models;final class Plan extends Model{protected static string $table='plans';protected static array $json=['name','description','features','highlights'];public const ALL_FEATURES=['ai_motion','ai_person','ai_vehicle','ai_animal','zones','lines','multi_site','priority_support','ptz','onvif','api','notifications','ai_llm'];public static function findBySlug(string $m):?array{return static::findBy('slug',$m);}public static function publicPlans():array{return static::castAll(static::query()->where('is_active',1)->where('is_public',1)->orderBy('sort')->get());}public static function activePlans():array{return static::castAll(static::query()->where('is_active',1)->orderBy('sort')->get());}public static function price(array $q,string $b):int{return $b==='year'?(int)$q['price_year']:(int)$q['price_month'];}public static function toApi(array $b):array{return['slug'=>$b['slug'],'name'=>$b['name'],'description'=>$b['description'],'price_month'=>(int)$b['price_month'],'price_year'=>(int)$b['price_year'],'currency'=>$b['currency'],'max_cameras'=>$b['max_cameras']===null?null:(int)$b['max_cameras'],'retention_days'=>(int)$b['retention_days'],'features'=>$b['features'],'trial_days'=>(int)$b['trial_days']];}}